def transform(A, B):
    if len(A) != len(B):
        return -1

    count_A = {}
    count_B = {}

    for char in A:
        count_A[char] = count_A.get(char, 0) + 1

    for char in B:
        count_B[char] = count_B.get(char, 0) + 1

    if count_A != count_B:
        return -1

    i, j = len(A) - 1, len(B) - 1
    steps = 0

    while i >= 0 and j >= 0:
        if A[i] == B[j]:
            i -= 1
            j -= 1
        else:
            i -= 1
            steps += 1

    return steps

